/* Group courts share the original 12 volleyball zones; extra capacity is a bench.
 * Historical members without a position receive an explicitly demo assignment. */
const groupCourtSelections=new Map(),groupCourtTabs=new Map();
const groupFieldSlots=slotLayout.map(([slot])=>slot);
function groupBenchSlots(group){return Array.from({length:Math.max(0,group.capacity-12)},(_,i)=>'r'+(i+1));}
function groupPositionLabel(slot){return slot.startsWith('r')?I18n.t('Riserva')+' '+slot.slice(1):I18n.t('Posizione')+' '+slotLabel(slot);}
function groupOrganizerName(group){return group.ownerId==='me'?($('#editName').value||group.ownerName||I18n.t('Tu')):(group.ownerName||I18n.t('Organizzatore demo'));}
const syncGroupCardsBeforeOrganizer=syncGroupExploreCards;
syncGroupExploreCards=function(){syncGroupCardsBeforeOrganizer();document.querySelectorAll('#games [data-organized-group]').forEach(card=>{const group=demoGroups.find(g=>g.id===card.dataset.organizedGroup);if(!group)return;const label=document.createElement('small');label.className='explore-organizer';I18n.html(label,'<span>Organizzatore</span>: <span data-no-i18n>'+htmlText(groupOrganizerName(group))+'</span>');card.querySelector('.group-name').after(label);});filterExploreGames();};
function normalizeGroupPositions(group){const slots=groupFieldSlots.concat(groupBenchSlots(group)),used=new Set();let changed=false;for(const member of group.members){if(!slots.includes(member.position)||used.has(member.position)){member.position=slots.find(slot=>!used.has(slot));member.positionAuto=true;changed=true;}if(member.position)used.add(member.position);}if(group.ownerId==='me'&&!group.ownerName){group.ownerName=$('#editName').value||'Tu';changed=true;}if(changed)saveGroups();}
function groupMemberFace(member){const photo=member.id==='me'?localStorage.getItem('staseravolley-v001-photo'):member.photo;return photo?'<img src="'+htmlText(photo)+'" alt="">':htmlText(initials(member.id==='me'?($('#editName').value||member.name):member.name));}
function groupSeatContent(group,slot){const member=group.members.find(m=>m.position===slot);const name=member?(member.id==='me'?($('#editName').value||member.name):member.name):I18n.t('Posto libero');return '<span class="seat-number">'+(slot.startsWith('r')?'R'+slot.slice(1):slotLabel(slot))+'</span><span class="seat-face">'+(member?groupMemberFace(member):'+')+'</span><span class="seat-name" data-no-i18n>'+htmlText(name)+(member?.id==='me'?' · '+I18n.t('Tu'):'')+'</span>';}
function chooseGroupSeat(group,slot){if(groupHasStarted(group))return;const mine=group.members.find(m=>m.id==='me');if(group.members.some(m=>m.position===slot&&m.id!=='me')||(!mine&&!freePlaces(group)))return;groupCourtSelections.set(group.id,slot);renderGroupDetail();const target=mine?$('#confirmGroupSeat'):$('#joinGroup');if(target&&!target.disabled){target.classList.add('booking-ready');target.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth',block:'center'});target.focus({preventScroll:true});}}
function selectGroupCourtTab(group,value){groupCourtTabs.set(group.id,value);for(const button of $('#groupDetail').querySelectorAll('[data-group-court-tab]')){const selected=button.dataset.groupCourtTab===value;button.setAttribute('aria-selected',String(selected));button.tabIndex=selected?0:-1;document.getElementById(button.getAttribute('aria-controls')).hidden=!selected;}}
const groupDetailBeforeCourt=renderGroupDetail;
renderGroupDetail=function(){groupDetailBeforeCourt();const group=activeGroup();if(!group)return;normalizeGroupPositions(group);const root=$('#groupDetail'),summary=root.querySelector('.group-detail-grid > article'),members=root.querySelector('.group-detail-grid > article:nth-child(2)');const organizer=document.createElement('p');organizer.className='group-organizer';const label=document.createElement('span');I18n.text(label,'Organizzatore');const name=document.createElement('strong');name.textContent=groupOrganizerName(group);name.dataset.noI18n='';organizer.append(label,document.createTextNode(': '),name);summary.querySelector('h1').after(organizer);
 // Keep the existing participant list and invitation/edit controls intact.
 members.querySelectorAll('.group-participant').forEach((row,index)=>{const member=group.members[index];if(member.id===group.ownerId){const badge=document.createElement('span');badge.className='organizer-badge';I18n.text(badge,'Organizzatore');row.querySelector('.person-copy').append(badge);}const position=document.createElement('small');position.className='group-member-position';position.textContent=groupPositionLabel(member.position);row.querySelector('.person-copy').append(position);});
 const view=document.createElement('section');view.className='group-court-view';I18n.html(view,'<div class="match-tabs" role="tablist" aria-label="Dettaglio partita"><button id="groupTabCourt" role="tab" data-group-court-tab="court" aria-controls="groupCourtPanel" aria-selected="true">Campo</button><button id="groupTabParticipants" role="tab" data-group-court-tab="participants" aria-controls="groupParticipantsPanel" aria-selected="false">Partecipanti ('+group.members.length+')</button></div><div id="groupCourtPanel" role="tabpanel" aria-labelledby="groupTabCourt"><div class="court group-court"><div class="court-floor" id="groupCourtFloor"></div><span class="court-label"></span></div><div class="court-legend"><span>Il tuo posto</span><span>Squadra A</span><span>Squadra B</span></div><div id="groupBench"></div><p class="groups-note">Disposizione iniziale automatica della demo; puoi scegliere il tuo posto.</p><button type="button" class="secondary-cta" id="confirmGroupSeat" hidden>Conferma posizione</button></div><div id="groupParticipantsPanel" role="tabpanel" aria-labelledby="groupTabParticipants" hidden></div>');summary.after(view);view.querySelector('#groupParticipantsPanel').append(members);
 if(!group.members.some(member=>member.id===group.ownerId)){const ownerRow=document.createElement('div');ownerRow.className='organizer-only';const owner=document.createElement('strong');owner.dataset.noI18n='';owner.textContent=groupOrganizerName(group);const role=document.createElement('small');role.className='group-member-position';I18n.text(role,'Organizzatore · non iscritto alla partita');ownerRow.append(owner,role);members.querySelector('h2').after(ownerRow);}
 const actions=document.createElement('article');actions.className='card form-card group-management';view.after(actions);for(const id of ['joinGroup','findGroupPlayers','editGroup','duplicateGroup']){const button=$('#'+id);if(button)actions.append(button);}const invitationNote=summary.querySelector('p.groups-note');if(invitationNote)actions.append(invitationNote);
 const mine=group.members.find(m=>m.id==='me'),selected=groupCourtSelections.get(group.id),started=groupHasStarted(group);const selectable=slot=>!started&&!group.members.some(m=>m.position===slot)&&(!!mine||freePlaces(group)>0);
 const floor=$('#groupCourtFloor');floor.innerHTML=groupFieldSlots.map(slot=>{const member=group.members.find(m=>m.position===slot),[x,y]=volleyballCoordinates[slot];return '<button type="button" class="court-player '+(slot.startsWith('q')?'team-own ':'')+(member?'occupied ':'open ')+(member?.id==='me'?'your-position ':'')+(selected===slot?'chosen ':'')+'" style="left:'+x+'%;top:'+y+'%" data-group-seat="'+slot+'" '+(!selectable(slot)?'disabled':'')+' aria-label="'+htmlText(groupPositionLabel(slot)+' · '+(member?.name||I18n.t('Posto libero')))+'">'+groupSeatContent(group,slot)+'</button>';}).join('')+'<span class="court-net" aria-hidden="true"></span>';
 const bench=groupBenchSlots(group);if(bench.length){I18n.insert($('#groupBench'),'beforeend','<h3>Riserve</h3>');const list=document.createElement('div');list.className='group-bench-list';list.innerHTML=bench.map(slot=>{const member=group.members.find(m=>m.position===slot);return '<button type="button" class="group-bench-seat '+(member?.id==='me'?'your-position ':'')+(selected===slot?'chosen':'')+'" data-group-seat="'+slot+'" '+(!selectable(slot)?'disabled':'')+' aria-label="'+htmlText(groupPositionLabel(slot))+'">'+groupSeatContent(group,slot)+'</button>';}).join('');$('#groupBench').append(list);}
 I18n.text(view.querySelector('.court-label'),freePlaces(group)+' posti disponibili');view.querySelectorAll('[data-group-seat]').forEach(button=>button.onclick=()=>chooseGroupSeat(group,button.dataset.groupSeat));view.querySelectorAll('[data-group-court-tab]').forEach((button,index)=>{button.onclick=()=>selectGroupCourtTab(group,button.dataset.groupCourtTab);button.onkeydown=e=>{if(['ArrowLeft','ArrowRight','Home','End'].includes(e.key)){e.preventDefault();const next=e.key==='Home'?0:e.key==='End'?1:1-index;const target=view.querySelectorAll('[data-group-court-tab]')[next];selectGroupCourtTab(group,target.dataset.groupCourtTab);target.focus();}};});selectGroupCourtTab(group,groupCourtTabs.get(group.id)||'court');
 const confirm=$('#confirmGroupSeat');confirm.hidden=!mine||!selected||selected===mine.position;confirm.disabled=started||!selected||group.members.some(m=>m.position===selected&&m.id!=='me');confirm.onclick=()=>{if(!mine||confirm.disabled||groupHasStarted(group))return;mine.position=selected;mine.positionAuto=false;groupCourtSelections.delete(group.id);saveGroups();renderGroups();renderGroupDetail();toast('Posizione aggiornata');};
 const join=$('#joinGroup');if(mine){const cancel=join.onclick;join.disabled=started;join.onclick=()=>{groupCourtSelections.delete(group.id);cancel();};}else{join.disabled=started||!freePlaces(group)||!selected||group.members.some(m=>m.position===selected);I18n.text(join,started?'La partita è iniziata: le modifiche sono bloccate.':selected?'Prenota un posto':'Seleziona un posto sul campo');join.onclick=()=>{if(groupHasStarted(group)||!freePlaces(group)||!selected||group.members.some(m=>m.position===selected)||group.members.some(m=>m.id==='me'))return;group.members.push({id:'me',name:$('#editName').value||'Tu',role:playerRole(),position:selected,positionAuto:false});groupCourtSelections.delete(group.id);saveGroups();renderGroups();renderGroupDetail();toast('Posto prenotato nel gruppo');};}
};
